{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Physostigmine, a carbamate ester, is reported to have poor oral bioavailability in patients, supporting low F for the carbamate-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Agomelatine has absolute oral bioavailability below 5% in humans, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "BMS-187745 showed mean absolute bioavailability of 2.6% after oral solution in healthy subjects, indicating low oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Tilidine systemic availability was approximately 3-7.6% in humans, consistent with low oral bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues consistently show low oral bioavailability, mostly below 10%, and the query's quaternary ammonium carbamate structure is expected to be poorly absorbed; therefore low is predicted.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the exact quaternary pyridinium carbamate; extrapolation relies on high-transfer analogues with different scaffolds.",
    "One analogue (naltrexone) shows wide 5-40% variability, adding some uncertainty but not overriding the consistent low-bioavailability evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

